<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_login();
$canSuppliers=has_permission('suppliers.manage');$canOrders=has_permission('purchase_orders.manage');
if(!$canSuppliers&&!$canOrders){http_response_code(403);exit('Procurement access is not assigned to your account.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');
 if($action==='supplier'){
  require_permission('suppliers.manage');$name=trim((string)($_POST['name']??''));$contact=trim((string)($_POST['contact_person']??''));$phone=trim((string)($_POST['phone']??''));$email=strtolower(trim((string)($_POST['email']??'')));$address=trim((string)($_POST['address']??''));
  if($name===''||strlen($name)>160||strlen($contact)>160||strlen($phone)>40||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))||strlen($email)>190||strlen($address)>255){set_flash('danger','Check the supplier details.');redirect('/hospital%20management/inventory/purchases.php');}$q=$pdo->prepare('INSERT INTO suppliers(name,contact_person,phone,email,address) VALUES(:name,:contact,:phone,:email,:address)');$q->execute(['name'=>$name,'contact'=>$contact?:null,'phone'=>$phone?:null,'email'=>$email?:null,'address'=>$address?:null]);$id=(string)$pdo->lastInsertId();record_audit('create','supplier',$id,'Supplier created');set_flash('success','Supplier saved.');
 }elseif($action==='order'){
  require_permission('purchase_orders.manage');$supplier=filter_var($_POST['supplier_id']??'',FILTER_VALIDATE_INT);$item=filter_var($_POST['inventory_item_id']??'',FILTER_VALIDATE_INT);$quantity=filter_var($_POST['quantity']??'',FILTER_VALIDATE_INT);$cost=trim((string)($_POST['unit_cost']??''));
  if(!$supplier||!$item||!$quantity||$quantity<1||$quantity>1000000||!preg_match('/^\d{1,10}(?:\.\d{1,2})?$/',$cost)){set_flash('danger','Choose a supplier and stock item, and enter a valid quantity and unit cost.');redirect('/hospital%20management/inventory/purchases.php');}$orderNo='PO-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$q=$pdo->prepare('INSERT INTO purchase_orders(order_no,supplier_id,inventory_item_id,quantity,unit_cost,created_by) VALUES(:number,:supplier,:item,:quantity,:cost,:user)');$q->execute(['number'=>$orderNo,'supplier'=>$supplier,'item'=>$item,'quantity'=>$quantity,'cost'=>$cost,'user'=>current_user()['id']]);$id=(string)$pdo->lastInsertId();record_audit('create','purchase_order',$id,'Purchase order '.$orderNo.' created');set_flash('success','Purchase order '.$orderNo.' created.');
 }elseif($action==='receive'){
  require_permission('purchase_orders.manage');$id=filter_var($_POST['order_id']??'',FILTER_VALIDATE_INT);$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT inventory_item_id,quantity,status FROM purchase_orders WHERE id=:id FOR UPDATE');$q->execute(['id'=>$id]);$order=$q->fetch();if(!$order||$order['status']!=='ordered')throw new RuntimeException('Only open purchase orders can be received.');$pdo->prepare('UPDATE inventory SET quantity=quantity+:quantity WHERE id=:item')->execute(['quantity'=>$order['quantity'],'item'=>$order['inventory_item_id']]);$pdo->prepare("UPDATE purchase_orders SET status='received',received_at=NOW() WHERE id=:id")->execute(['id'=>$id]);record_audit('receive','purchase_order',(string)$id,'Purchase order received; stock increased');$pdo->commit();set_flash('success','Order received and inventory stock updated.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();set_flash('danger',$e instanceof RuntimeException?$e->getMessage():'Purchase order could not be received.');}
 }else{http_response_code(400);exit('Unknown procurement action.');}redirect('/hospital%20management/inventory/purchases.php');
}
$suppliers=$pdo->query('SELECT id,name,contact_person,phone,email FROM suppliers ORDER BY name')->fetchAll();$items=$pdo->query('SELECT id,item_name,category,quantity,unit FROM inventory ORDER BY item_name')->fetchAll();$orders=$pdo->query('SELECT po.id,po.order_no,po.quantity,po.unit_cost,po.status,po.created_at,po.received_at,s.name AS supplier,i.item_name,i.unit FROM purchase_orders po JOIN suppliers s ON s.id=po.supplier_id JOIN inventory i ON i.id=po.inventory_item_id ORDER BY po.created_at DESC LIMIT 300')->fetchAll();
$pageTitle='Suppliers and purchase orders';require __DIR__.'/../includes/header.php';?>
<div class="page-heading"><div><h2>Suppliers and purchase orders</h2><p>Track suppliers and receive ordered stock into the inventory register.</p></div><a class="btn btn-outline-secondary" href="/hospital%20management/inventory/index.php">Inventory</a></div>
<?php if($canSuppliers):?><section class="content-card form-card mt-0"><div class="card-heading"><h3>Add supplier</h3></div><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="supplier"><div class="col-md-3"><label class="form-label">Supplier name</label><input class="form-control" name="name" maxlength="160" required></div><div class="col-md-2"><label class="form-label">Contact person</label><input class="form-control" name="contact_person" maxlength="160"></div><div class="col-md-2"><label class="form-label">Phone</label><input class="form-control" name="phone" maxlength="40"></div><div class="col-md-2"><label class="form-label">Email</label><input class="form-control" type="email" name="email" maxlength="190"></div><div class="col-md-2"><label class="form-label">Address</label><input class="form-control" name="address" maxlength="255"></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-primary">Save</button></div></form></section><?php endif;?>
<?php if($canOrders):?><section class="content-card form-card"><div class="card-heading"><h3>Create purchase order</h3></div><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="order"><div class="col-md-4"><label class="form-label">Supplier</label><select class="form-select" name="supplier_id" required><option value="">Select supplier</option><?php foreach($suppliers as $s):?><option value="<?=(int)$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Stock item</label><select class="form-select" name="inventory_item_id" required><option value="">Select item</option><?php foreach($items as $i):?><option value="<?=(int)$i['id']?>"><?=e($i['item_name'].' · '.$i['quantity'].' '.$i['unit'].' in stock')?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Quantity</label><input class="form-control" type="number" name="quantity" min="1" max="1000000" required></div><div class="col-md-2"><label class="form-label">Unit cost</label><input class="form-control" type="number" name="unit_cost" min="0.01" step="0.01" required></div><div class="col-12"><button class="btn btn-primary">Create order</button></div></form></section><?php endif;?>
<section class="content-card"><div class="card-heading"><h3>Purchase order register</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Order</th><th>Supplier</th><th>Item</th><th>Quantity</th><th>Unit cost</th><th>Created</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$orders):?><tr><td colspan="8" class="empty-state">No purchase orders recorded.</td></tr><?php else:foreach($orders as $o):?><tr><td><?=e($o['order_no'])?></td><td><?=e($o['supplier'])?></td><td><?=e($o['item_name'])?></td><td><?=(int)$o['quantity']?> <?=e($o['unit'])?></td><td><?=number_format((float)$o['unit_cost'],2)?></td><td><?=e(date('M j, Y',strtotime($o['created_at'])))?></td><td><?=e(ucfirst($o['status']))?></td><td><?php if($canOrders&&$o['status']==='ordered'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="receive"><input type="hidden" name="order_id" value="<?=(int)$o['id']?>"><button class="btn btn-sm btn-primary">Receive and add stock</button></form><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section>
<section class="content-card"><div class="card-heading"><h3>Suppliers</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>Contact</th><th>Phone</th><th>Email</th></tr></thead><tbody><?php if(!$suppliers):?><tr><td colspan="4" class="empty-state">No suppliers recorded.</td></tr><?php else:foreach($suppliers as $s):?><tr><td><?=e($s['name'])?></td><td><?=e($s['contact_person']?:'—')?></td><td><?=e($s['phone']?:'—')?></td><td><?=e($s['email']?:'—')?></td></tr><?php endforeach;endif;?></tbody></table></div></section>
<?php require __DIR__.'/../includes/footer.php';?>
